def leer_matriz():
    filas = int(input())
    cols = int(input())
    m = [None] * filas
    for i in range(filas):
        partes = input().split()
        m[i] = [0] * cols
        for j in range(cols):
            m[i][j] = int(partes[j])
    return m


def mostrar(m):
    for i in range(len(m)):
        for j in range(len(m[i])):
            print(m[i][j], end=' ')
        print()


